// Verified hub URLs (HTTP 200, tested 2026-09-18). See scraper/seed_urls.py
const seeds = [
  { issuer_name: 'AMFI India (Regulatory)', product_category: 'mutual_fund', source_url: 'https://portal.amfiindia.com', page_type: 'regulatory_hub', verified_status: 200 },
  { issuer_name: 'AMFI India (Regulatory)', product_category: 'mutual_fund', source_url: 'https://portal.amfiindia.com/DownloadSchemeData_Po.aspx?mf=0', page_type: 'regulatory_data', verified_status: 200 },
  { issuer_name: 'ICICI Prudential Mutual Fund', product_category: 'mutual_fund', source_url: 'https://www.icicipruamc.com/downloads', page_type: 'amc_downloads_hub', verified_status: 200 },
  { issuer_name: 'Mirae Asset Mutual Fund', product_category: 'mutual_fund', source_url: 'https://www.miraeassetmf.co.in/downloads/factsheet', page_type: 'amc_factsheet_hub', verified_status: 200 },
  { issuer_name: 'PPFAS Mutual Fund', product_category: 'mutual_fund', source_url: 'https://amc.ppfas.com/schemes/parag-parikh-flexi-cap-fund/', page_type: 'amc_scheme_hub', verified_status: 200 },
  { issuer_name: 'Nippon India Mutual Fund', product_category: 'mutual_fund', source_url: 'https://mf.nipponindiaim.com/investor-services/downloads', page_type: 'amc_downloads_hub', verified_status: 200 },
  { issuer_name: 'UTI Mutual Fund', product_category: 'mutual_fund', source_url: 'https://www.utimf.com/downloads/factsheets', page_type: 'amc_factsheet_hub', verified_status: 200 }
];
return seeds.map(s => ({ json: s }));

// Flatten, deduplicate, and resolve relative PDF URLs.
const items = $input.all();
const results = [];
for (const item of items) {
  const baseUrl = item.json.source_url || '';
  const rawLinks = item.json.pdf_links || [];
  const seen = new Set();
  for (const link of rawLinks) {
    if (!link || seen.has(link)) continue;
    seen.add(link);
    let absoluteUrl = link;
    if (link.startsWith('/')) {
      try { const base = new URL(baseUrl); absoluteUrl = base.origin + link; } catch(_) {}
    } else if (!link.startsWith('http')) { continue; }
    results.push({ json: { pdf_url: absoluteUrl, issuer_name: item.json.issuer_name, product_category: item.json.product_category, page_type: item.json.page_type, source_hub_url: baseUrl, discovered_at: new Date().toISOString() } });
  }
}
return results.length > 0 ? results : [{ json: { pdf_url: null, issuer_name: 'NO_PDFS_FOUND', source_hub_url: items[0]?.json?.source_url || '' } }];

const failureCount = $input.all().length;
const THRESHOLD = 3;
if (failureCount >= THRESHOLD) {
  return [{ json: { alert: true, message: `Scrape job: ${failureCount} sources failed.`, failure_count: failureCount, threshold: THRESHOLD, alerted_at: new Date().toISOString() } }];
}
return [{ json: { alert: false, failure_count: failureCount } }];

